DB=dict(no=6,name='DB손해보험 (005830)',sub='보험 · 이익의 질과 자본',tag='INSURANCE',
 lead=('DB손해보험은 장기보험(건강·상해 등)과 자동차보험, 일반보험을 판매하는 손해보험사다. 이번 Monthly에서는 장기금리가 높고 변동성이 큰 10월에 흔들리지 않는 이익을 가진 완충 자산으로 편입했다. '+Q('확인할 것은 장기보험 이익이 일회성 요인 없이 지속되고, 낮아진 자본비율이 주주환원 여력을 지킬 수 있는가다.')),
 ov=[('01 사업','장기보험·자동차보험·일반보험을 판매하는 손해보험사. 보험료를 받아 운용하고 보험금을 지급하며 이익을 낸다'),
     ('02 투자 연관','금리 수혜가 아니라 높은 장기금리와 변동성 속에서도 흔들리지 않는 이익. 포트폴리오의 변동성 완충'),
     ('03 이익 구조','이익의 중심은 장기보험손익과 CSM(보험계약마진) 상각. 6월 말 CSM 잔액 12조 8,000억원, 2분기 장기보험손익 5,105억원')],
 a=[P('주가·거래량','9월 30일 종가 185,900원, 전일 대비 2.97% 하락. 2월 23일 고점 237,000원 대비 21.56% 낮고 1월 14일 저점 120,600원 대비로는 54.15% 높다. 60·120일 이동평균선이 우상향하는 가운데 주가는 30일 20일선 아래로 내려왔다.'),
    P('투자 논리','보험주를 금리 수혜로만 보지 않는다. 10월에 필요한 것은 장기금리가 높고 변동성이 큰 환경에서도 흔들리지 않는 이익이며, DB손해보험의 이익은 장기보험손익과 CSM 상각이 중심이다. CSM은 이미 판매한 보험계약에서 앞으로 인식될 이익의 저장고여서, 잔액이 유지되는 한 장기보험손익이 매 분기 상각을 통해 나온다.'),
    P('펀더멘털','2분기 순이익은 7,111억원으로 54.6% 늘어 분기 최대였고, 보험손익 5,618억원(+109.9%) 가운데 장기보험이 5,105억원(+98.6%)이었다. 6월 말 CSM 잔액은 원수 기준 12조 8,000억원이다. 장기보험손익이 보험손익의 91%를 차지해 이익의 중심이 장기보험이라는 점이 숫자로 확인된다. '+E('다만 상반기 순이익 9,796억원에서 2분기를 빼면 1분기는 2,685억원이어서 분기 이익의 변동이 컸다.')),
    dfig('dbins','DB손해보험 이익의 지속성 · 일회성 · 자본 여력 진단','자료: DB손해보험 2026년 1·2분기 실적, DART180 리서치. 2025년 2분기 장기보험손익은 증가율로 역산, 1분기 순이익은 상반기에서 2분기를 뺀 값'),
    P('사업 구조','손해보험사의 이익은 보험손익과 투자손익으로 나뉘고, 보험손익은 다시 장기보험과 자동차보험·일반보험으로 나뉜다. 2분기 보험손익은 대부분 장기보험에서 나왔고 자동차보험의 기여는 미미했다. 이익의 질을 보려면 장기보험손익이 손해율 개선과 CSM 상각처럼 반복되는 항목에서 나왔는지, 손실계약 환입 같은 일회성 항목에서 나왔는지를 구분해야 한다.')],
 b=[P('밸류에이션','보험주의 가격 판단은 PER보다 이익의 지속성과 자본비율에 좌우된다. 주가는 2월 고점 대비 21.56% 낮지만 2분기 사상 최대 이익에는 반복되기 어려운 환입이 섞여 있어, 낙폭만으로 저평가를 판단하지 않는다. K-ICS 비율이 200%대 초반으로 내려온 만큼 자본 여력이 주주환원의 상한을 정한다. '+E('완충 자산의 역할은 높은 이익 레벨이 아니라 흔들리지 않는 이익에서 나온다.')),
    P('판단','9월 Monthly에서는 이익 추정치 상향 강도가 같은 업종의 다른 종목에 뒤져 관심종목으로 뒀다. 2분기 실적은 그 전에 발표돼 승격의 근거가 아니며, 9월에 장기금리가 높아지고 변동성이 커져 이익 변동이 작은 완충 자산의 역할이 커진 점을 근거로 올렸다. 이 역할은 위험선호에 민감한 디지털자산과 반대편에 있다. 2분기 개선에는 장기위험 손해율 개선과 함께 손실계약 환입이 포함됐고 자동차보험 손익은 62억원으로 80.6% 줄었으며, 상반기 순이익은 9,796억원(+8.0%)이다. 손실계약 환입은 반복되기 어려운 항목이므로 저평가 논리보다 이익의 지속성으로 판단한다.'),
    P('기술적 위치·판단','1월 14일 저점에서 2월 23일 고점까지 급등한 뒤 7월까지 조정을 거쳤고, 8월 이후 다시 고점을 높였다. 60일선(약 17.7만원)과 120일선(약 16.4만원)이 우상향하는 가운데 주가는 20일선(약 19만원) 부근에서 움직인다. 9월 3일 약 20.8만원 고점 이후 18만~20만원에서 쉬다가 30일 20일선 아래로 밀려 '+E('추세는 살아 있지만 속도는 느려졌다.')+' 60일선 지지가 유지되는 한 완충 역할은 유효하다.'),
    table('DB손해보험 가격 확인 구간',[
     ('2차 저항','237,000원','2월 고점','저항'),
     ('1차 저항','20.5만~20.8만원','9월 고점. 돌파 시 추세 재가속','확인'),
     ('현재 위치','185,900원','9월 30일 종가. 20일선(약 19만원) 하회, 상승 추세 속 숨 고르기','밀집'),
     ('1차 지지','17.7만~18만원','60일선과 9월 저점','지지'),
     ('중기 방어선','약 16.4만원','120일선. 이탈 시 상승 추세 훼손','무효화')],PZSRC),
    chart('dbins','DB손해보험 일봉 차트와 우상향 60·120일선'),
    P('대응','수익보다 변동성 완충이 목적이므로 비중을 제한해 담는다. 3분기 실적은 11월 중순 발표 예정이어서 10월에는 월별 손해율과 장기금리 경로, K-ICS 비율로 먼저 점검한다. K-ICS 비율은 3월 말 232.1%에서 6월 말 204.3%로 27.8%p 낮아졌다. 추가 하락으로 주주환원 여력이 줄거나 장기보험손익이 1분기 수준으로 되돌아가면 이익의 질 논리를 철회한다.')],
 summary=[('01 판단','장기보험손익과 CSM이 이익의 중심인 완충 자산. 2분기 사상 최대 이익에는 손실계약 환입이 섞여 있어 지속성으로 판단'),
          ('02 확인','월별 손해율, 장기금리 경로, K-ICS 비율(6월 말 204.3%), 11월 중순 3분기 실적의 장기보험손익'),
          ('03 리스크','K-ICS 비율 추가 하락으로 주주환원 여력 축소, 장기보험손익의 1분기 수준 회귀, 120일선(약 16.4만원) 이탈')])
